"""Normalize release records at the input boundary.

This module owns input validation, change identity and replay handling. It
returns plain dictionaries and sets; it never builds a graph or orders changes.
"""


class JournalError(ValueError):
    pass


def _is_identifier(value):
    return isinstance(value, str) and value != ""


def _read_dependencies(row):
    """Return the dependency set of one record, or raise ``invalid-change``."""
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    member_list = []
    for dependency in depends_on:
        if not _is_identifier(dependency):
            raise JournalError("invalid-change")
        member_list.append(dependency)
    # ``depends_on`` is a set of change IDs, so repeats carry no extra meaning.
    return frozenset(member_list)


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Equality covers id, component, units and the set of dependencies. Two
    records that share an ID but differ in any of those fail as
    ``conflicting-change``. The surviving records keep first-seen order.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not _is_identifier(row.get("id"))
                or not _is_identifier(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row),
        }
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = change
            changes.append(change)
        elif (previous["component"] != change["component"]
                or previous["units"] != change["units"]
                or previous["depends_on"] != change["depends_on"]):
            raise JournalError("conflicting-change")
    return changes


def read_applied(applied):
    """Validate the persisted journal of already applied change IDs."""
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    ids = []
    for identifier in applied:
        if not _is_identifier(identifier):
            raise JournalError("invalid-change")
        ids.append(identifier)
    return set(ids)

