"""Compose policy and journal data into a plan.

This module owns graph construction, dependency ordering and result assembly.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(identifiers, units):
    return {"status": "ok", "actions": list(identifiers), "units": units}


class GraphError(ValueError):
    pass


def _build_graph(changes, applied):
    """Validate graph targets and the applied journal.

    Returns ``(by_id, prerequisite_ids)`` where prerequisites are the ordered,
    de-duplicated dependency IDs of each change.
    """
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in by_id:
                raise GraphError("unknown-dependency")
    for identifier in applied:
        if identifier not in by_id:
            raise GraphError("unknown-dependency")
    prerequisites = {identifier: sorted(change["depends_on"]) for identifier, change in by_id.items()}
    return by_id, prerequisites


def topological_order(by_id, prerequisites):
    """Kahn's algorithm with lexicographic tie-breaking on eligible IDs."""
    remaining = {identifier: len(prerequisites[identifier]) for identifier in by_id}
    dependents = {identifier: [] for identifier in by_id}
    for identifier, dependencies in prerequisites.items():
        for dependency in dependencies:
            dependents[dependency].append(identifier)
    ready = [identifier for identifier, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        identifier = heapq.heappop(ready)
        order.append(identifier)
        for dependent in dependents[identifier]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        raise GraphError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    try:
        by_id, prerequisites = _build_graph(changes, applied)
        order = topological_order(by_id, prerequisites)
    except GraphError as exc:
        return failure(str(exc))

    if action == "rollback":
        # Budget was validated for shape only; rollback is never capped by it.
        identifiers = [identifier for identifier in reversed(order) if identifier in applied]
    else:
        # Applied entries satisfy dependencies but emit nothing and cost nothing.
        identifiers = [identifier for identifier in order if identifier not in applied]

    units = sum(by_id[identifier]["units"] for identifier in identifiers)
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return success(identifiers, units)

