    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not _is_identifier(row.get("id"))
                or not _is_identifier(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row),
        }
        previous = seen.get(change["id"])
        if previous is None:
            seen[change["id"]] = change
            changes.append(change)
        elif (previous["component"] != change["component"]
                or previous["units"] != change["units"]
                or previous["depends_on"] != change["depends_on"]):
            raise JournalError("conflicting-change")
    return changes


def read_applied(applied):
    """Validate the persisted journal of already applied change IDs."""
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    ids = []
    for identifier in applied:
        if not _is_identifier(identifier):
            raise JournalError("invalid-change")
        ids.append(identifier)
    return set(ids)


def read_retain(retain, applied):
    """Validate the rollback keep-list against the applied journal.

    ``retain`` defaults to empty. Every listed ID must be an applied change ID;
    a malformed list or one naming an unapplied (or unknown) change fails as
    ``invalid-retain``. Repeats carry no extra meaning, so the result is a set.
    """
    if not isinstance(retain, list):
        raise JournalError("invalid-retain")
    ids = set()
    for identifier in retain:
        if not _is_identifier(identifier) or identifier not in applied:
            raise JournalError("invalid-retain")
        ids.add(identifier)
    return ids

