"""Compose policy and journal data into a plan.

This module owns graph construction, dependency ordering and result assembly.
"""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, check_environment, limit_for

# G2: a staging plan may emit at most this many units, whatever the request asks.
STAGING_PLAN_LIMIT = 3


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(identifiers, units):
    return {"status": "ok", "actions": list(identifiers), "units": units}


class GraphError(ValueError):
    pass


def _build_graph(changes, applied):
    """Validate graph targets and the applied journal.

    Returns ``(by_id, prerequisite_ids)`` where prerequisites are the ordered,
    de-duplicated dependency IDs of each change.
    """
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in by_id:
                raise GraphError("unknown-dependency")
    for identifier in applied:
        if identifier not in by_id:
            raise GraphError("unknown-dependency")
    prerequisites = {identifier: sorted(change["depends_on"]) for identifier, change in by_id.items()}
    return by_id, prerequisites


def topological_order(by_id, prerequisites):
    """Kahn's algorithm with lexicographic tie-breaking on eligible IDs."""
    remaining = {identifier: len(prerequisites[identifier]) for identifier in by_id}
    dependents = {identifier: [] for identifier in by_id}
    for identifier, dependencies in prerequisites.items():
        for dependency in dependencies:
            dependents[dependency].append(identifier)
    ready = [identifier for identifier, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        identifier = heapq.heappop(ready)
        order.append(identifier)
        for dependent in dependents[identifier]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        raise GraphError("dependency-cycle")
    return order


def _retained_closure(prerequisites, retained, applied):
    """Collect every applied change a retained change still needs.

    Dependencies of a retained change must already be applied, so their removal
    would leave a broken release; each of those is kept in turn, together with
    its own applied dependencies.
    """
    kept = set(retained)
    pending = list(retained)
    while pending:
        for dependency in prerequisites[pending.pop()]:
            if dependency in applied:
                if dependency not in kept:
                    kept.add(dependency)
                    pending.append(dependency)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # G2: the production freeze is decided before graph or change validation.
    try:
        check_environment(request)
    except PolicyError as exc:
        return failure(str(exc))
    try:
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
    except JournalError as exc:
        return failure(str(exc))
    try:
        action, budget = limit_for(request)
    except PolicyError as exc:
        return failure(str(exc))
    try:
        by_id, prerequisites = _build_graph(changes, applied)
        order = topological_order(by_id, prerequisites)
        # Only rollback carries keep-list semantics; ``retain`` is ignored by plan.
        retained = read_retain(request.get("retain", []), applied) if action == "rollback" else set()
    except (JournalError, GraphError) as exc:
        return failure(str(exc))

    if action == "rollback":
        # Budget was validated for shape only; rollback is never capped by it.
        kept = _retained_closure(prerequisites, retained, applied)
        identifiers = [identifier for identifier in reversed(order)
                       if identifier in applied and identifier not in kept]
    else:
        # Applied entries satisfy dependencies but emit nothing and cost nothing.
        identifiers = [identifier for identifier in order if identifier not in applied]

    units = sum(by_id[identifier]["units"] for identifier in identifiers)
    if action == "plan":
        # G2: the effective budget is the smaller of the request budget and the
        # staging limit. The check runs on the executed step sequence, the way
        # the original request-budget check did, so a change that cannot fit
        # stops the plan at its own position instead of being skipped.
        limit = min(budget, STAGING_PLAN_LIMIT)
        spent = 0
        for identifier in order:
            if identifier in applied:
                continue
            spent += by_id[identifier]["units"]
            if spent > limit:
                return failure("budget-exceeded")
    return success(identifiers, units)

