"""Normalize release records at the input boundary.

This module owns input validation, record identity (replay/deduplication) and
the dependency graph. It never decides ordering policy or budget enforcement.
"""

DEFAULT_DEPENDENCIES = ()
DEFAULT_APPLIED = ()


class JournalError(ValueError):
    pass


def _is_text(value):
    return isinstance(value, str) and bool(value)


def _is_positive_int(value):
    # Booleans are ints in Python but are not integers for this contract.
    return type(value) is int and value > 0


def _read_dependencies(row):
    raw = row.get("depends_on", DEFAULT_DEPENDENCIES)
    if not isinstance(raw, (list, tuple)):
        raise JournalError("invalid-change")
    dependencies = []
    for dep in raw:
        if not _is_text(dep):
            raise JournalError("invalid-change")
        dependencies.append(dep)
    return dependencies


def _read_change(row):
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    change_id = row.get("id")
    component = row.get("component")
    units = row.get("units")
    if not _is_text(change_id) or not _is_text(component) or not _is_positive_int(units):
        raise JournalError("invalid-change")
    return change_id, component, units, _read_dependencies(row)


def _canonical(component, units, dependencies):
    # Equality for duplicate records covers id, component, units and the set of
    # dependencies; ordering within depends_on is not significant.
    return (component, units, frozenset(dependencies))


def read_changes(records):
    """Return deduplicated changes in first-seen order.

    Each change is a dict with ``id``, ``component``, ``units`` and a sorted
    ``dependencies`` tuple. Identical duplicates collapse; conflicting ones fail.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        change_id, component, units, dependencies = _read_change(row)
        key = _canonical(component, units, dependencies)
        if change_id in seen:
            if seen[change_id] != key:
                raise JournalError("conflicting-change")
            continue
        seen[change_id] = key
        changes.append(
            {
                "id": change_id,
                "component": component,
                "units": units,
                "dependencies": tuple(sorted(dependencies)),
            }
        )
    return changes


def read_applied(raw):
    """Return the persisted release journal as a set of change IDs."""
    if raw is None:
        return set()
    if not isinstance(raw, (list, tuple)):
        raise JournalError("invalid-change")
    applied = set()
    for entry in raw:
        if not _is_text(entry):
            raise JournalError("invalid-change")
        applied.add(entry)
    return applied


def build_graph(changes, applied):
    """Index changes by ID and validate graph targets and the applied journal."""
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for dep in change["dependencies"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
    for entry in applied:
        if entry not in by_id:
            raise JournalError("unknown-dependency")
    return by_id


def read_request(request):
    """Normalize a validated request into its change list, applied set and graph."""
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied"))
    by_id = build_graph(changes, applied)
    return changes, applied, by_id

