"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_request
from policy import PolicyError, effective_plan_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Deterministic topological order, lexicographic among currently eligible IDs."""
    pending = {change["id"]: len(change["dependencies"]) for change in changes}
    dependents = {change_id: [] for change_id in pending}
    for change in changes:
        for dep in change["dependencies"]:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(pending):
        # Every edge target is validated earlier, so a shortfall is a cycle.
        raise JournalError("dependency-cycle")
    return order


def _retained_closure(by_id, applied, retain):
    """Applied dependencies needed, transitively, by the retained changes."""
    retained = set(retain)
    pending = list(retain)
    while pending:
        change_id = pending.pop()
        for dep in by_id[change_id]["dependencies"]:
            if dep in applied and dep not in retained:
                retained.add(dep)
                pending.append(dep)
    return frozenset(retained)


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        environment, action, budget = limit_for(request)
        changes, applied, by_id, retain = read_request(request, action)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if action == "rollback":
        kept = _retained_closure(by_id, applied, retain)
        actions = [change_id for change_id in reversed(order) if change_id in applied and change_id not in kept]
    else:
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(by_id[change_id]["units"] for change_id in actions)
    if action == "plan" and units > effective_plan_budget(environment, budget):
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

