    lexicographic id order via a heap. The result depends only on the
    change graph, never on ``applied``: ``plan`` and ``rollback`` both
    filter this one order (forward / reversed) so they cannot disagree.
    """
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in by_id:
                raise PlanError("unknown-dependency")
    # Every dependency edge counts, including edges to already-applied
    # changes. The order must be a function of the graph alone: if replay
    # removed those edges, a partially applied journal would yield a
    # different order than a fully applied one and rollback/specced
    # reversal would drift. Applied entries are filtered out *after* the
    # full order is built, never while building it.
    blockers = {}
    dependents = {change_id: [] for change_id in by_id}
    for change_id, row in by_id.items():
        unmet = list(row["depends_on"])
        blockers[change_id] = len(unmet)
        for dep in unmet:
            dependents[dep].append(change_id)
    ready = [change_id for change_id, count in blockers.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            blockers[dependent] -= 1
            if blockers[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        # Anything left is on or behind a cycle; SPEC fails on any cycle.
        raise PlanError("dependency-cycle")
    return order


def retained_closure(retain, applied, by_id):
    """Return the applied IDs that a rollback must leave in place.

    The closure is ``retain`` plus every transitive dependency of a retained
    change that is itself applied: you cannot remove a dependency while the
    dependent stays installed. Dependencies that are not applied are skipped
    rather than added -- they are not part of the rollback set, and graph
    validation has already rejected missing targets. A retained ID that is not
    applied (or unknown) is ``invalid-retain``: SPEC makes retain a subset of
    the journal, and silently dropping it would let a caller believe something
    was protected when it is not.
    """
    for change_id in retain:
        if change_id not in applied:
            raise PlanError("invalid-retain")
    keep = set()
    pending = list(retain)
    while pending:
        change_id = pending.pop()
        if change_id in keep:
            continue
        keep.add(change_id)
        for dep in by_id[change_id]["depends_on"]:
            if dep in applied and dep not in keep:
                pending.append(dep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        action = request["action"]
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        retain = read_retain(request, action)
        by_id = {row["id"]: row for row in changes}
        for change_id in applied:
            if change_id not in by_id:
                raise PlanError("unknown-dependency")
        order = topological_order(changes)
        if action == "plan":
            emitted = [change_id for change_id in order if change_id not in applied]
        else:
            # G2 staging rollback. Reverse the full order so dependents are
            # removed before the changes they rest on; retained changes and
            # their applied dependencies are filtered out of that same order,
            # so the surviving actions keep the original reverse sequence.
            # Budget is validated, never capped here.
            keep = retained_closure(retain, applied, by_id)
            emitted = [change_id for change_id in reversed(order)
                       if change_id in applied and change_id not in keep]
        units = sum(by_id[change_id]["units"] for change_id in emitted)
        check_budget(action, budget, units)
    except (PolicyError, JournalError, PlanError) as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": emitted, "units": units}

